import {
  RatingGroup as RatingGroupPrimitive,
  useRatingGroup,
  useRatingGroupContext,
  useRatingGroupItemContext,
} from '@ark-ui/solid/rating-group';
import { clsx } from 'clsx';
import type { ComponentProps, JSX } from 'solid-js';
import { children, For, splitProps } from 'solid-js';
import { callEventHandler } from '@/lib/moduix/callEventHandler';
import { RatingStarIcon } from '@/lib/moduix/icons/ui';
import styles from './RatingGroup.module.css';

type RatingGroupSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

type RatingGroupRootProps = ComponentProps<typeof RatingGroupPrimitive.Root> & {
  size?: RatingGroupSize;
};

type RatingGroupRootProviderProps = ComponentProps<typeof RatingGroupPrimitive.RootProvider> & {
  size?: RatingGroupSize;
};

type RatingGroupItemIndicatorProps = ComponentProps<'span'>;

function RatingGroup(props: RatingGroupRootProps) {
  const [local, others] = splitProps(props, ['class', 'size']);

  return (
    <RatingGroupPrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="rating-group-root"
    />
  );
}

function RatingGroupRootProvider(props: RatingGroupRootProviderProps) {
  const [local, others] = splitProps(props, ['class', 'size']);

  return (
    <RatingGroupPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="rating-group-root-provider"
    />
  );
}

function RatingGroupLabel(props: ComponentProps<typeof RatingGroupPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <RatingGroupPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="rating-group-label"
    />
  );
}

function RatingGroupControl(props: ComponentProps<typeof RatingGroupPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <RatingGroupPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="rating-group-control"
    />
  );
}

function RatingGroupItem(props: ComponentProps<typeof RatingGroupPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class', 'onPointerDown']);

  return (
    <RatingGroupPrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      onPointerDown={(event) => {
        callEventHandler(local.onPointerDown, event);

        if (event.button !== 0) return;
        if (event.currentTarget.matches('[data-disabled], [data-readonly]')) return;

        event.currentTarget.focus({ preventScroll: true, focusVisible: false });
      }}
      data-slot="rating-group-item"
    />
  );
}

function RatingGroupItemIndicator(props: RatingGroupItemIndicatorProps) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);
  const item = useRatingGroupItemContext();

  return (
    <span
      class={clsx(styles.itemIndicator, local.class)}
      {...others}
      data-half={item().half ? '' : undefined}
      data-highlighted={item().highlighted ? '' : undefined}
      data-slot="rating-group-item-indicator"
    >
      {resolvedChildren() ?? (
        <>
          <RatingStarIcon data-slot="rating-group-item-indicator-bg" class={styles.iconBg} />
          <RatingStarIcon data-slot="rating-group-item-indicator-fg" class={styles.iconFg} />
        </>
      )}
    </span>
  );
}

function RatingGroupItems(props: { children?: JSX.Element }) {
  return (
    <RatingGroupPrimitive.Context>
      {(ratingGroup) => (
        <For each={ratingGroup().items}>
          {(item) => (
            <RatingGroupItem index={item}>
              {props.children ?? <RatingGroupItemIndicator />}
            </RatingGroupItem>
          )}
        </For>
      )}
    </RatingGroupPrimitive.Context>
  );
}

const RatingGroupContext = RatingGroupPrimitive.Context;
const RatingGroupHiddenInput = RatingGroupPrimitive.HiddenInput;
const RatingGroupItemContext = RatingGroupPrimitive.ItemContext;

export {
  RatingGroup,
  RatingGroupContext,
  RatingGroupControl,
  RatingGroupHiddenInput,
  RatingGroupItem,
  RatingGroupItemContext,
  RatingGroupItemIndicator,
  RatingGroupItems,
  RatingGroupLabel,
  RatingGroupRootProvider,
  useRatingGroup,
  useRatingGroupContext,
  useRatingGroupItemContext,
};
export type {
  RatingGroupItemIndicatorProps,
  RatingGroupRootProps,
  RatingGroupRootProviderProps,
  RatingGroupSize,
};

@layer moduix.components {
  .root {
    --_rating-group-icon-size: var(--moduix-spacing-5);

    display: inline-flex;
    flex-direction: column;
    gap: var(--moduix-spacing-1);

    &[data-size='xs'] {
      --_rating-group-icon-size: var(--moduix-spacing-3-5);
    }

    &[data-size='sm'] {
      --_rating-group-icon-size: var(--moduix-spacing-4);
    }

    &[data-size='lg'] {
      --_rating-group-icon-size: var(--moduix-spacing-6);
    }

    &[data-size='xl'] {
      --_rating-group-icon-size: var(--moduix-spacing-7);
    }
  }

  .label {
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .control {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-rating-group-gap, var(--moduix-spacing-1));

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .item {
    display: inline-flex;
    border-radius: var(--moduix-radius-sm);
    cursor: pointer;

    &[data-readonly],
    &[data-disabled] {
      cursor: default;
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }
  }

  .itemIndicator {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-rating-group-icon-size, var(--_rating-group-icon-size));
    height: var(--moduix-rating-group-icon-size, var(--_rating-group-icon-size));
    color: var(--moduix-rating-group-active-color, var(--moduix-color-primary));

    & > svg {
      flex: none;
      width: 100%;
      height: 100%;
      transition:
        color var(--moduix-transition-default),
        fill var(--moduix-transition-default),
        clip-path var(--moduix-transition-default);
    }
  }

  .iconBg {
    position: absolute;
    inset: 0;
    color: var(--moduix-rating-group-color, var(--moduix-color-muted-foreground));
    fill: transparent;
    stroke: currentColor;
  }

  /* The filled star inherits the indicator color and is clipped from Ark item state. */
  .iconFg {
    position: absolute;
    inset: 0;
    fill: currentColor;
    stroke: currentColor;
    clip-path: inset(0);

    [data-half] > & {
      clip-path: inset(0 50% 0 0);

      &:dir(rtl) {
        clip-path: inset(0 0 0 50%);
      }
    }

    :not([data-highlighted]) > & {
      clip-path: inset(0 100% 0 0);
    }
  }
}
